-- Idempotent install for public.knowledge_provenance
-- Auto-generated from dbanalytics_install.backup. Safe to re-run (psql -f).

CREATE SCHEMA IF NOT EXISTS public;

CREATE SEQUENCE IF NOT EXISTS public.knowledge_provenance_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE IF NOT EXISTS public.knowledge_provenance (
    id integer NOT NULL,
    entity_type character varying(30) NOT NULL,
    entity_id integer NOT NULL,
    generated_at timestamp with time zone DEFAULT now() NOT NULL,
    generated_by character varying(100) NOT NULL,
    model_id character varying(100),
    source_description text,
    input_hash character varying(64),
    reviewed_by character varying(100),
    reviewed_at timestamp with time zone,
    confidence numeric(3,2),
    notes text,
    CONSTRAINT knowledge_provenance_confidence_check CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric)))
);

ALTER TABLE public.knowledge_provenance ALTER COLUMN id SET DEFAULT nextval('public.knowledge_provenance_id_seq'::regclass);
ALTER SEQUENCE public.knowledge_provenance_id_seq OWNED BY public.knowledge_provenance.id;

-- data: load only into a freshly-created (empty) table
DROP TABLE IF EXISTS _stg_load;
CREATE TEMP TABLE _stg_load (LIKE public.knowledge_provenance);
SELECT id, entity_type, entity_id, generated_at, generated_by, model_id, source_description, input_hash, reviewed_by, reviewed_at, confidence, notes FROM _stg_load
WHERE NOT EXISTS (SELECT 1 FROM public.knowledge_provenance);
DROP TABLE _stg_load;

SELECT setval('public.knowledge_provenance_id_seq', GREATEST((SELECT COALESCE(max(id),0) FROM public.knowledge_provenance),1), (SELECT count(*) FROM public.knowledge_provenance) > 0);

DO $do$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint con
        JOIN pg_class c ON c.oid = con.conrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND c.relname = 'knowledge_provenance'
          AND con.conname = 'knowledge_provenance_entity_type_entity_id_key') THEN
        ALTER TABLE ONLY public.knowledge_provenance
    ADD CONSTRAINT knowledge_provenance_entity_type_entity_id_key UNIQUE (entity_type, entity_id);
    END IF;
END $do$;
DO $do$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint con
        JOIN pg_class c ON c.oid = con.conrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND c.relname = 'knowledge_provenance'
          AND con.conname = 'knowledge_provenance_pkey') THEN
        ALTER TABLE ONLY public.knowledge_provenance
    ADD CONSTRAINT knowledge_provenance_pkey PRIMARY KEY (id);
    END IF;
END $do$;

CREATE INDEX IF NOT EXISTS idx_provenance_entity ON public.knowledge_provenance USING btree (entity_type, entity_id);
CREATE INDEX IF NOT EXISTS idx_provenance_unreviewed ON public.knowledge_provenance USING btree (entity_type) WHERE (reviewed_by IS NULL);
